// Times prompts against a running even-terminal: node drive.mjs <port> <token> <sessionId|new> <text>
const [port, token, sid, text] = process.argv.slice(2);
const base = `http://127.0.0.1:${port}/api`;
const headers = { Authorization: `Bearer ${token}`, "Content-Type": "application/json" };

const t0 = Date.now();
const res = await fetch(`${base}/prompt`, {
    method: "POST",
    headers,
    body: JSON.stringify({ text, sessionId: sid === "new" ? undefined : sid, provider: "claude" }),
});
const { sessionId, error } = await res.json();
if (error) throw new Error(error);

let after = 0;
let firstText = null;
while (Date.now() - t0 < 180000) {
    const r = await fetch(`${base}/messages?sessionId=${sessionId}&after=${after}&provider=claude`, { headers });
    const body = await r.json();
    for (const m of body.messages ?? body) {
        after = Math.max(after, m.id);
        if (m.type === "text_delta" && firstText === null) firstText = Date.now() - t0;
        if (m.type === "result") {
            console.log(JSON.stringify({ sessionId, firstTextMs: firstText, totalMs: Date.now() - t0, text: m.text.slice(0, 120) }));
            process.exit(0);
        }
    }
    await new Promise((r) => setTimeout(r, 100));
}
throw new Error("timed out waiting for result");
